// Maps a wttr.in WWO condition code (one-line %i) to an icon bitmap,
// picking the night variant when available. Returns nullptr if unknown.
static inline const unsigned char* weatherIconForCode(int code, bool night)
{
  switch (code)
  {
    case 113: return night ? icon_sun_night : icon_sun;
    case 116: return night ? icon_partly_night : icon_partly;
    case 119: return icon_cloud;
    case 122: return icon_cloud;
    case 143: return night ? icon_fog_night : icon_fog;
    case 176: return night ? icon_rain_night : icon_rain;
    case 179: return icon_sleet;
    case 182: return icon_sleet;
    case 185: return icon_sleet;
    case 200: return icon_thunder;
    case 227: return night ? icon_snow_night : icon_snow;
    case 230: return night ? icon_snow_night : icon_snow;
    case 248: return night ? icon_fog_night : icon_fog;
    case 260: return night ? icon_fog_night : icon_fog;
    case 263: return night ? icon_rain_night : icon_rain;
    case 266: return night ? icon_rain_night : icon_rain;
    case 281: return icon_sleet;
    case 284: return icon_sleet;
    case 293: return night ? icon_rain_night : icon_rain;
    case 296: return night ? icon_rain_night : icon_rain;
    case 299: return icon_heavy_rain;
    case 302: return icon_heavy_rain;
    case 305: return icon_heavy_rain;
    case 308: return icon_heavy_rain;
    case 311: return icon_sleet;
    case 314: return icon_sleet;
    case 317: return icon_sleet;
    case 320: return night ? icon_snow_night : icon_snow;
    case 323: return night ? icon_snow_night : icon_snow;
    case 326: return night ? icon_snow_night : icon_snow;
    case 329: return night ? icon_snow_night : icon_snow;
    case 332: return night ? icon_snow_night : icon_snow;
    case 335: return night ? icon_snow_night : icon_snow;
    case 338: return night ? icon_snow_night : icon_snow;
    case 350: return icon_sleet;
    case 353: return night ? icon_rain_night : icon_rain;
    case 356: return icon_heavy_rain;
    case 359: return icon_heavy_rain;
    case 362: return icon_sleet;
    case 365: return icon_sleet;
    case 368: return night ? icon_snow_night : icon_snow;
    case 371: return night ? icon_snow_night : icon_snow;
    case 374: return icon_sleet;
    case 377: return icon_sleet;
    case 386: return icon_thunder;
    case 389: return icon_thunder;
    case 392: return icon_thunder;
    case 395: return night ? icon_snow_night : icon_snow;
    default: return nullptr;
  }
}
